from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

# TLS 1.3 Constants
CONTENT_TYPE_CHANGE_CIPHER_SPEC = 20
CONTENT_TYPE_APPLICATION_DATA = 23
TLS_VERSION_1_3 = (0x03, 0x03)

# AEAD Parameters (Example: AES-128-GCM)
KEY_SIZE = 16  # 128 bits
IV_SIZE = 12   # 96 bits for GCM
TAG_SIZE = 16  # 128 bits for GCM

def create_tls_record(content_type, data):
    """Create a basic TLS 1.3 record structure."""
    version = struct.pack('!BB', *TLS_VERSION_1_3)
    length = struct.pack('!H', len(data))
    return version + struct.pack('!B', content_type) + length + data

def encrypt_record(key, iv, plaintext):
    """Encrypt plaintext using AES-128-GCM."""
    nonce = os.urandom(IV_SIZE)
    cipher = Cipher(algorithms.AES(key), modes.GCM(nonce), backend=default_backend())
    encryptor = cipher.encryptor()
    ciphertext = encryptor.update(plaintext) + encryptor.finalize()
    tag = encryptor.tag
    return nonce + ciphertext + tag

def craft_all_zero_record(key, iv):
    """Craft a TLS 1.3 record that decrypts to all-zero bytes."""
    # The plaintext should be all zeros, including the content type byte.
    # This forces the receiver to scan the entire record for a non-zero byte.
    plaintext = b'\x00' * 100  # 100 bytes of zeros
    encrypted = encrypt_record(key, iv, plaintext)
    return create_tls_record(CONTENT_TYPE_APPLICATION_DATA, encrypted)

def send_record(sock, record):
    """Send a TLS record over a socket."""
    sock.sendall(record)

def receive_response(sock, timeout=5):
    """Receive and parse the server's response."""
    sock.settimeout(timeout)
    try:
        response = sock.recv(4096)
        if not response:
            return "Connection closed by server"
        
        # Parse TLS record
        if len(response) < 5:
            return "Malformed response"
        
        version = response[:2]
        content_type = response[2]
        length = struct.unpack('!H', response[3:5])[0]
        payload = response[5:5+length]
        
        if content_type == 21:  # Alert
            alert_level = payload[0]
            alert_description = payload[1]
            return f"Alert received: Level={alert_level}, Description={alert_description}"
        else:
            return f"Unexpected response: Content Type={content_type}, Length={length}"
    except socket.timeout:
        return "Timeout waiting for response"
    except Exception as e:
        return f"Error: {str(e)}"

